Definition km_pre (kel data sy sx : Z) (rows : list Z) : list (Z * Z) := rev (map (fun r => (r, 4 * sx)) rows) ++ [(data, 8 * sy); (kel, 24)].
Lemma km_live_app : forall kel data sy sx rows (L : list (Z * Z)), km_live kel data sy sx rows L = km_pre kel data sy sx rows ++ L.
