Lemma km_unlive_mid : forall (X : list (Z * Z)) kel data sy sx rows (L : list (Z * Z)),
  List.NoDup (map fst (X ++ km_live kel data sy sx rows L)) ->
  km_unlive kel data rows (X ++ km_live kel data sy sx rows L) = X ++ L.
